definition.script:
pipeline {
  agent any
  stages {
    stage('checkout') {
      steps {
        sh 'rm -f -- changeset.intent changelog.intent'
        checkout([$class: 'GitSCM',
          branches: [[name: 'refs/heads/main']],
          userRemoteConfigs: [[url: 'file:///fixture/repo']]])
      }
    }
    stage('changeset-predicate') {
      when { changeset pattern: '**/*.target', caseSensitive: true }
      steps { writeFile file: 'changeset.intent', text: 'selected\n' }
    }
    stage('changelog-predicate') {
      when { changelog 'MIG005A-MATCH' }
      steps { writeFile file: 'changelog.intent', text: 'selected\n' }
    }
    stage('effect-free-state') {
      steps {
        writeFile file: 'persistent.state', text: "build=${env.BUILD_NUMBER}\n"
      }
    }
  }
  post {
    always {
      archiveArtifacts artifacts: '*.intent,persistent.state', allowEmptyArchive: false,
        fingerprint: true
    }
  }
}
